#!/usr/bin/env bash
# -*- coding: utf-8 -*-
# VERSION: 0.75.3
# AUTHORS: Ogekuri
##
# @file scripts/clean.sh
# @brief Remove every build artifact generated by scripts/build.sh from the repository.
# @details Executes the following ordered stages from the repository root resolved from
# this script location (SRS-559):
# 1. `environment`: verify the `git` command is executable (SRS-560).
# 2. `dist-cleanup`: remove from `dist/` every entry that is not git-tracked and remove
#    the `dist/` directory itself when it is empty after the removal (SRS-561).
# 3. `intermediate-cleanup`: remove the `build/` directory and every `src/*.egg-info`
#    directory created by `scripts/build.sh` (SRS-562).
# 4. `summary`: print every removed and every skipped path (SRS-564).
# Every removal target containing git-tracked files is preserved and reported with an
# English warning identifying the skipped path (SRS-563). Every stage runs unconditionally
# under `set -e`, so the first failing command aborts the script; the EXIT trap then prints
# `Repository clean failed at stage <stage>.` and exits with code 1. Exit code 0 is
# returned only when every stage succeeds (SRS-564). Absent cleanup targets are a no-op,
# making the script idempotent and safe to run right after a fresh checkout.
# @retval 0 Every build artifact was removed or preserved per the git-tracked policy.
# @retval 1 A stage failed or `git` is unavailable.
# @warning Requires `bash` and `git`; never deletes git-tracked content.
# @see scripts/build.sh
# @see scripts/pre-release-check.sh
# @satisfies SRS-559, SRS-560, SRS-561, SRS-562, SRS-563, SRS-564
##

set -euo pipefail

##
# @brief Default exit code for every repository clean failure path.
# @details Single constant shared by the EXIT trap and stage failure paths so all failure
# exits stay uniform (SRS-564).
# @satisfies SRS-564
CLEAN_ERROR_EXIT_CODE=1

##
# @brief Name of the currently executing stage used by failure diagnostics.
# @details Mutated by `run_stage` before each stage invocation and consumed by `on_exit`
# to print the canonical `Repository clean failed at stage <stage>.` message (SRS-564).
# @satisfies SRS-564
CURRENT_STAGE=""

##
# @brief Repository-relative paths removed during the current execution.
# @details Populated by `remove_untracked_target` and consumed by `print_clean_summary`;
# declared before any stage runs so `set -u` never observes an unset array (SRS-564).
# @satisfies SRS-564
REMOVED_TARGETS=()

##
# @brief Repository-relative paths skipped because they contain git-tracked files.
# @details Populated by `remove_untracked_target` and consumed by `print_clean_summary`;
# declared before any stage runs so `set -u` never observes an unset array (SRS-563,
# SRS-564).
# @satisfies SRS-563, SRS-564
SKIPPED_TARGETS=()

##
# @brief Terminate the clean with the canonical stage-failure diagnostic on any failing exit.
# @details Installed as the EXIT trap. Reads the terminating status from `$?`; when the
# status is non-zero it prints `Repository clean failed at stage <stage>.` on stderr if a
# stage was running and exits with `CLEAN_ERROR_EXIT_CODE`. A zero status returns without
# output, so the successful path keeps exit code 0 (SRS-564). Stage functions are invoked
# without any conditional wrapper (see `run_stage`), so `set -e` remains active inside
# every stage body and no failure is masked.
# @return Does not return on failure; returns 0 on successful termination.
# @note Complexity: O(1). Side effects: writes one diagnostic line to stderr on failure.
# @satisfies SRS-564
on_exit() {
  local status=$?
  if [ "${status}" -ne 0 ]; then
    if [ -n "${CURRENT_STAGE}" ]; then
      echo "Repository clean failed at stage ${CURRENT_STAGE}." >&2
    fi
    exit "${CLEAN_ERROR_EXIT_CODE}"
  fi
}
trap on_exit EXIT

##
# @brief Resolve the absolute repository root from this script filesystem location.
# @details Mirrors the resolution logic of `scripts/build.sh`: canonicalize `$0` through
# `readlink -f`, derive the script directory, and step one level up. All stages execute
# with this root so the caller working directory never influences behavior (SRS-559).
# @return Prints nothing; sets the global `BASE_DIR` variable to the absolute repository root.
# @satisfies SRS-559
FULL_PATH="$(readlink -f "$0")"
SCRIPT_PATH="$(dirname "$FULL_PATH")"
BASE_DIR="$(dirname "$SCRIPT_PATH")"

##
# @brief Execute one cleanup stage under unconditional `set -e` semantics.
# @details Assigns `CURRENT_STAGE` from the first argument, prints a progress line on
# stdout, then executes the remaining arguments as a plain command. The command is never
# placed in an `if`, `||`, `&&`, or `!` context: Bash disables `set -e` for every command
# executed in those contexts, including nested function bodies, which would mask failures.
# A non-zero status therefore terminates the script immediately and `on_exit` reports the
# failing stage (SRS-564).
# @param[in] $1 Stage identifier used in progress and failure diagnostics.
# @param[in] $2... Command and arguments composing the stage.
# @return Returns the stage status when it is zero; otherwise terminates via `set -e`.
# @satisfies SRS-564
run_stage() {
  CURRENT_STAGE="$1"
  shift
  printf '[clean] stage %s\n' "${CURRENT_STAGE}"
  "$@"
}

##
# @brief Stage `environment`: verify that the `git` command is executable (SRS-560).
# @details Emits an English error on stderr and returns non-zero when `git` is absent,
# because every removal decision depends on `git ls-files` tracked-file classification.
# @return Returns 0 when `git` is available; returns 1 otherwise.
# @satisfies SRS-560
check_git_available() {
  if ! command -v git >/dev/null 2>&1; then
    echo "ERROR: git command not found in PATH" >&2
    return "${CLEAN_ERROR_EXIT_CODE}"
  fi
}

##
# @brief Remove one cleanup target unless it contains git-tracked files.
# @details An absent target is a no-op, keeping every stage idempotent. The target is
# classified through `git ls-files`: when any tracked entry exists beneath it, the target
# is preserved, an English warning identifying the repository-relative path is printed on
# stderr, and the path is recorded in `SKIPPED_TARGETS` (SRS-563); otherwise the target is
# deleted with `rm -rf` and recorded in `REMOVED_TARGETS`. A failing `git` or `rm` command
# aborts the owning stage under `set -e`. Complexity O(T) over the tracked entries beneath
# the target; side effects: deletes untracked filesystem entries, mutates the summary arrays.
# @param[in] $1 Absolute path of the cleanup target inside the repository.
# @return Returns 0 after removal, preservation, or no-op; non-zero when a removal fails.
# @satisfies SRS-563
remove_untracked_target() {
  local target="$1"
  [ -e "${target}" ] || return 0
  local relative_target="${target#"${BASE_DIR}/"}"
  local tracked_files
  tracked_files="$(git -C "${BASE_DIR}" ls-files -- "${relative_target}")"
  if [ -n "${tracked_files}" ]; then
    echo "WARNING: cleanup skipped for '${relative_target}' because it contains git-tracked files" >&2
    SKIPPED_TARGETS+=("${relative_target}")
    return 0
  fi
  rm -rf -- "${target}"
  REMOVED_TARGETS+=("${relative_target}")
}

##
# @brief Stage `dist-cleanup`: remove the untracked release artifacts stored in dist/.
# @details Enumerates the direct children of `dist/` into a variable through command
# substitution so a failing `find` terminates the stage under `set -e` instead of being
# silently discarded by a process substitution. Every entry is delegated to
# `remove_untracked_target`, so only entries without git-tracked content are deleted
# (SRS-561, SRS-563). After the loop, `rmdir` removes the `dist/` directory itself only
# when it is empty; a non-empty survivor (git-tracked entries) is tolerated. An absent
# `dist/` directory is a no-op, making the stage idempotent for fresh checkouts.
# Complexity O(N) over the direct children of `dist/`.
# @return Returns 0 after cleaning or when `dist/` is absent; non-zero when a removal fails.
# @satisfies SRS-561
clean_dist_artifacts() {
  [ -d "${BASE_DIR}/dist" ] || return 0
  local entries
  local entry
  entries="$(find "${BASE_DIR}/dist" -mindepth 1 -maxdepth 1 -print)"
  if [ -n "${entries}" ]; then
    while IFS= read -r entry; do
      remove_untracked_target "${entry}"
    done <<< "${entries}"
  fi
  rmdir "${BASE_DIR}/dist" 2>/dev/null || true
}

##
# @brief Stage `intermediate-cleanup`: remove the setuptools build intermediates.
# @details Removes the `build/` directory produced by the sdist build and every
# `src/*.egg-info` directory produced by the setuptools metadata generation of
# `scripts/build.sh` (SRS-562); each target is delegated to `remove_untracked_target`,
# so targets containing git-tracked files are preserved with a warning (SRS-563).
# Absent targets are a no-op, keeping the stage idempotent. Complexity O(K) over K
# egg-info directories; side effects: deletes untracked intermediates.
# @return Returns 0 after cleaning or when no candidate exists; non-zero when a removal fails.
# @satisfies SRS-562
clean_build_intermediates() {
  remove_untracked_target "${BASE_DIR}/build"
  [ -d "${BASE_DIR}/src" ] || return 0
  local egg_dirs
  local egg_dir
  egg_dirs="$(find "${BASE_DIR}/src" -mindepth 1 -maxdepth 1 -type d -name '*.egg-info' -print)"
  if [ -z "${egg_dirs}" ]; then
    return 0
  fi
  while IFS= read -r egg_dir; do
    remove_untracked_target "${egg_dir}"
  done <<< "${egg_dirs}"
}

##
# @brief Stage `summary`: report every removed and every skipped cleanup path.
# @details Prints the `REMOVED_TARGETS` and `SKIPPED_TARGETS` arrays accumulated by the
# previous stages as two labeled repository-relative path lists so the caller can record
# exactly which build artifacts the clean removed and which targets were preserved because
# they contain git-tracked files (SRS-563, SRS-564). Complexity O(N) over the recorded
# paths; side effects: stdout lines only.
# @return Returns 0 after printing the summary.
# @satisfies SRS-564
print_clean_summary() {
  local target
  printf '[clean] removed %d path(s):\n' "${#REMOVED_TARGETS[@]}"
  if [ "${#REMOVED_TARGETS[@]}" -gt 0 ]; then
    for target in "${REMOVED_TARGETS[@]}"; do
      printf '  %s\n' "${target}"
    done
  fi
  printf '[clean] skipped %d git-tracked path(s):\n' "${#SKIPPED_TARGETS[@]}"
  if [ "${#SKIPPED_TARGETS[@]}" -gt 0 ]; then
    for target in "${SKIPPED_TARGETS[@]}"; do
      printf '  %s\n' "${target}"
    done
  fi
}

cd "${BASE_DIR}"

run_stage "environment" check_git_available
run_stage "dist-cleanup" clean_dist_artifacts
run_stage "intermediate-cleanup" clean_build_intermediates
run_stage "summary" print_clean_summary
